from pathlib import Path
p=Path('tools/dev/pop-legend/codex')
figs=[('mula','Mulassa','Abans que s’acabi la metxa','+1'),('petard','Bomba','Toca per desactivar-la','Desactiva'),('drac','Drac','No el toquis','NO'),('dracFals','Drac vermell','No el toquis','NO'),('mulaFalsa','Mulassa verda','No la toquis','NO'),('calcot','Calçot','Toca: +5 punts','+5'),('campanar','Campanar','Toca: més lent durant 5 s','5 s'),('carretilla','Carretilla','Toca: crema totes les Mulasses','FOC')]
def img(i): return f'<img src="/jocs/pop/cards/{figs[i][0]}.png" alt="{figs[i][1]}" loading="eager">'
def people(ids): return '<div class="people">'+''.join(f'<figure>{img(i)}<figcaption>{figs[i][1]}</figcaption></figure>' for i in ids)+'</div>'
def extras():return '<div class="extras">'+''.join(f'<div>{img(i)}<b>{figs[i][1]}</b><span>{["+5 punts","Calma · 5 s","Crema totes les Mulasses"][i-5]}</span></div>' for i in range(5,8))+'</div>'
a=f'''<div class="poster"><div class="eyebrow">LA GUIA DE LA PLAÇA</div><h2>Toca amb cap!</h2><div class="poster-main"><div><strong>TOCA!</strong><p>Mulassa: +1 abans<br>que s’acabi la metxa.<br>Bomba: desactiva-la.</p></div>{people([0,1])}</div><div class="avoid"><strong>NI UN TOC</strong>{people([2,3,4])}</div><h3>Una ajuda? Toca-les!</h3>{extras()}<footer>Una vida. Que no peti la festa!</footer></div>'''
b=f'''<div class="badges"><h2>Cada toc compta</h2><p class="sub">Aprèn els tres gestos de la festa.</p><div class="badge-group"><div class="group-title"><i>↘</i><div><h3>Toca a temps</h3><p>No deixis que s’acabi la metxa.</p></div></div><div class="duo">{''.join(f'<div class="badge-person">{img(i)}<div><b>{figs[i][1]}</b><span>{["+1 punt","Desactiva-la"][i]}</span></div></div>' for i in [0,1])}</div></div><div class="badge-group danger"><div class="group-title"><i>×</i><div><h3>No les toquis</h3><p>Qualsevol d’aquestes et fa perdre.</p></div></div>{people([2,3,4])}</div><div class="badge-group"><div class="group-title"><i>✦</i><div><h3>Aprofita les ajudes</h3><p>Toca-les quan apareguin.</p></div></div>{extras()}</div></div>'''
c=f'''<div class="comic"><h2>Comença la festa!</h2><div class="panel one"><b class="step">01</b><div class="speech">La metxa corre.<br><strong>Toca abans que peti!</strong></div>{people([0,1])}<p>Mulassa: +1 · Bomba: desactiva-la</p><span class="zap">TOC!</span></div><div class="panel two"><b class="step">02</b><h3>Aquests? Mans quietes.</h3>{people([2,3,4])}<p>Si en toques un, s’acaba la partida.</p></div><div class="panel three"><b class="step">03</b><h3>Les ajudes sí que es toquen!</h3>{extras()}</div></div>'''
d='<div class="boardguide"><div class="eyebrow">GUIA DE BUTXACA</div><h2>Qui és qui al tauler?</h2><p class="sub">Mira la figura. Recorda el gest.</p><div class="tiles">'+''.join(f'<div class="tile {"skip" if i in [2,3,4] else ""}">{img(i)}<span class="tile-mark">{figs[i][3]}</span><b>{figs[i][1]}</b></div>' for i in range(8))+'</div><div class="key"><p><b>↘ Toca a temps</b>Mulassa: +1 abans que s’acabi la metxa. Bomba: desactiva-la.</p><p><b>× No toquis</b>Drac, Drac vermell i Mulassa verda.</p><p><b>✦ Toca les ajudes</b>Calçot: +5. Campanar: més lent, 5 s. Carretilla: crema totes les Mulasses.</p></div></div>'
css='''*{box-sizing:border-box}body{margin:0;background:#181729;color:#fff3d6;font:15px/1.4 system-ui,sans-serif}h1,h2,h3,p,figure{margin:0}h1{font-size:36px;letter-spacing:-1px}h2{font-size:27px;line-height:1.08;letter-spacing:-.7px}h3{font-size:16px}img{object-fit:contain;display:block}button,a,textarea{font:inherit}button,a{min-height:44px}a{color:inherit}header.review,main{max-width:1120px;margin:auto;padding:32px 24px}header.review p{max-width:680px;color:#c9c2d4;margin-top:12px}nav{display:flex;gap:8px;margin-top:24px}nav a{border:1px solid #77657f;border-radius:12px;padding:10px 20px;text-decoration:none}section{padding:32px 0;border-top:1px solid #494054;scroll-margin-top:12px}.intro{margin-bottom:24px}.intro h2{color:#ff7ac6}.intro p{margin-top:8px;max-width:720px;color:#c9c2d4}.samples{display:flex;align-items:flex-start;gap:32px;flex-wrap:wrap}.sample{width:375px;max-width:100%}.sample.sheet{width:360px}.label{font:12px/1.4 ui-monospace,monospace;letter-spacing:1px;color:#c9c2d4;margin-bottom:12px}.surface{background:#24223f;border:1px solid #6b5a76;border-radius:24px;overflow:hidden}.home-head{padding:24px 16px 20px;text-align:center;border-bottom:1px solid #ffffff18}.logo{font-size:23px;font-weight:950;color:#ff7ac6;letter-spacing:-1px}.play{display:block;border:0;background:#f5c518;color:#24223f;font-weight:850;border-radius:14px;padding:12px;margin:12px auto 0;min-width:168px}.sheet-head{padding:20px 16px;display:flex;align-items:center;justify-content:space-between}.sheet-head b{font-size:20px;color:#f5c518}.close{width:44px;height:44px;border:2px solid #f5c518;border-radius:50%;background:#24223f;color:#fff3d6;font-size:24px}.legend{padding:16px}.sheet .legend{padding-top:0}.people{display:flex;justify-content:space-evenly;gap:8px}.people figure{flex:1;min-width:0;text-align:center}.people img{height:76px;width:100%}.people figcaption{font-size:12px;line-height:1.2;font-weight:750;margin-top:8px}.extras{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;text-align:center}.extras img{width:100%;height:56px;margin-bottom:8px}.extras b,.extras span{display:block}.extras b{font-size:12px}.extras span{font-size:12px;line-height:1.3;margin-top:4px}.eyebrow{font-size:10px;font-weight:850;letter-spacing:2px}.poster{background:#fff3d6;color:#24223f;padding:20px 16px;border-radius:12px;text-align:center;border:3px solid #ff7ac6}.poster h2{font-size:36px;margin:8px 0 20px}.poster-main{border-top:2px solid #24223f;border-bottom:2px solid #24223f;padding:16px 0;display:grid;grid-template-columns:1fr 1.2fr;gap:8px;text-align:left;align-items:center}.poster-main strong{font-size:24px;color:#9e235d}.poster-main p{font-size:12px;margin-top:8px}.poster-main .people img{height:86px}.poster-main figcaption{display:none}.avoid{background:#24223f;color:#fff3d6;border-radius:8px;padding:12px 8px;margin-top:16px}.avoid>strong{font-size:13px;letter-spacing:2px;color:#ff7ac6}.avoid .people{margin-top:12px}.poster h3{margin:20px 0 12px}.poster footer{border-top:1px solid #24223f44;margin-top:16px;padding-top:12px;font-size:11px;font-weight:700}.badges h2{color:#ff7ac6}.sub{color:#c9c2d4;font-size:13px;margin:8px 0 20px}.badge-group{padding:16px 0;border-top:1px solid #ffffff25}.badge-group:last-child{padding-bottom:0}.group-title{display:flex;align-items:center;gap:12px;margin-bottom:16px}.group-title i{display:grid;place-items:center;background:#ff7ac6;color:#24223f;width:40px;height:40px;border-radius:12px;font-style:normal;font-size:27px;font-weight:bold;flex-shrink:0}.group-title p{font-size:12px;color:#c9c2d4;margin-top:4px}.danger .group-title i{background:#fff3d6}.duo{display:grid;grid-template-columns:1fr 1fr;gap:12px}.badge-person{display:flex;align-items:center;gap:8px}.badge-person img{width:56px;height:68px}.badge-person b,.badge-person span{display:block;font-size:12px}.badge-person span{color:#ff7ac6;margin-top:4px}.comic{color:#24223f}.comic>h2{color:#ff7ac6;margin-bottom:16px}.panel{position:relative;border:2px solid #111025;padding:16px;border-radius:8px;box-shadow:3px 3px 0 #111025;margin-top:12px;overflow:hidden}.one{background:#ff7ac6}.two{background:#fff3d6}.three{background:#e7c56b}.step{font-size:12px;display:block;margin-bottom:8px;opacity:.65}.speech{background:#fff3d6;border:2px solid #24223f;border-radius:12px;padding:10px 12px;width:max-content;font-size:13px;margin-bottom:16px}.one .people{padding-right:50px}.one .people img{height:90px}.panel>p{font-size:12px;margin-top:12px}.panel h3{margin-bottom:16px}.zap{position:absolute;right:12px;top:130px;font-size:24px;font-weight:950;transform:rotate(-12deg)}.boardguide h2{margin-top:8px;color:#ff7ac6}.tiles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.tile{border-radius:12px;background:linear-gradient(145deg,#514568,#302b47);border:1px solid #a18596;position:relative;min-height:116px;padding:12px 4px 8px;text-align:center}.tile img{width:100%;height:68px}.tile b{display:block;font-size:11px;margin-top:8px}.tile-mark{position:absolute;top:4px;right:4px;background:#ff7ac6;color:#24223f;padding:2px 5px;font-size:9px;font-weight:900;border-radius:4px}.skip .tile-mark{background:#fff3d6}.key{margin-top:16px;display:grid;gap:12px}.key p{font-size:12px;color:#ded4e0}.key b{display:block;font-size:13px;color:#fff3d6;margin-bottom:4px}.feedback{margin-top:24px;max-width:767px}.feedback label{display:block;font-size:13px;color:#c9c2d4}.feedback textarea{width:100%;margin-top:8px;border:1px solid #77657f;background:#24223f;color:#fff3d6;border-radius:12px;padding:12px;min-height:70px}.note{font-size:12px;color:#c9c2d4;margin-top:16px}.export{border:1px solid #f5c518;background:transparent;color:#fff3d6;border-radius:12px;padding:10px 16px}button:focus-visible,a:focus-visible,textarea:focus-visible{outline:3px solid #ff7ac6;outline-offset:3px}@media(max-width:480px){header.review,main{padding:24px 12px}h1{font-size:30px}.samples{gap:24px}.sample{width:375px}.sample.sheet{width:360px}.legend{padding:12px}.intro h2{font-size:24px}}'''
proposals=[('X1','El cartell de la festa','Una sola peça il·lustrada, amb titulars grans i tres franges per recordar què fer.','La versió crema dona protagonisme a les figures i funciona com un petit cartell dins del full.',a),('X2','Tres gestos','Insígnies i grups: toca a temps, no toquis i aprofita les ajudes.','La més compacta i directa per consultar-la sovint des del botó d’ajuda.',b),('X3','Una tira de festa','Tres vinyetes expliquen la partida en ordre, amb bafarada i un toc de còmic.','Pensada per a la primera visita; el mateix relat continua dins del full d’ajuda.',c),('X4','El tauler de butxaca','Vuit caselles com les del joc, cadascuna amb la seva pista curta.','Una clau al peu conserva tots els efectes sense tapar les figures amb text.',d)]
html='<!doctype html><html lang="ca"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mulassa Pop · Propostes X1–X4</title><style>'+css+'</style><body><header class="review"><div class="eyebrow">MULASSA POP · EXPLORACIÓ VISUAL</div><h1>Qui toca? Qui es queda?</h1><p>Quatre alternatives a la fila de cartes. Cada proposta es mostra sota Juga, a 375 px, i dins d’un full de 360 px. Textos provisionals. Retrats reals del joc.</p><nav>'+''.join(f'<a href="#{x[0]}">{x[0]}</a>' for x in proposals)+'</nav></header><main>'
for code,title,desc,desc2,content in proposals:
 html+=f'<section id="{code}"><div class="intro"><h2>{code} · {title}</h2><p>{desc}<br>{desc2}</p></div><div class="samples">'
 for sheet in [False,True]:
  head='<div class="sheet-head"><b>Com es juga</b><button class="close" aria-label="Tanca (mostra visual)">×</button></div>' if sheet else '<div class="home-head"><div class="logo">MULASSA POP</div><button class="play">Juga</button></div>'
  html+=f'<div class="sample {"sheet" if sheet else "phone"}"><p class="label">{code} · {"FULL D’AJUDA · 360 PX" if sheet else "INICI · 375 PX"}</p><div class="surface">{head}<div class="legend">{content}</div></div></div>'
 html+=f'</div><div class="feedback"><label for="note-{code}">Notes per a {code}</label><textarea id="note-{code}" placeholder="Què conservaries? Què canviaries?"></textarea></div></section>'
html+='''<button class="export" id="export">Copia les notes</button><p class="note" id="status" aria-live="polite">Maquetes estàtiques: Juga i × només mostren el context. Sense canvis al joc. No s’han executat tests ni s’ha mesurat el cost al Galaxy S10.</p></main><script>document.querySelector('#export').onclick=async()=>{const text=[...document.querySelectorAll('textarea')].map(t=>t.id.replace('note-','')+': '+t.value).join('\\n');try{await navigator.clipboard.writeText(text);document.querySelector('#status').textContent='Notes copiades.'}catch{document.querySelector('#status').textContent=text}};</script></body></html>'''
(p/'index.html').write_text(html)
